// Convierte el Markdown del agente a HTML de Telegram y lo divide en mensajes de máx. 3.800 caracteres
const LIMITE = 3800;
let t = String($input.first().json.output || '').trim();
if (!t) t = 'Uy, se me enredó el yipao 🚙💨. ¿Me repites tu mensaje, por favor?';

t = t
  .replace(/^[ \t]*\|?[ \t]*:?-{3,}.*\n?/gm, '')                         // separadores de tabla
  .replace(/^[ \t]*\|(.+)\|[ \t]*$/gm, (m, f) =>                          // filas de tabla -> viñetas
    '• ' + f.split('|').map(c => c.trim()).filter(Boolean).join(' — '))
  .replace(/^[ \t]*[-*][ \t]+/gm, '• ')                                  // viñetas
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')    // escapar HTML
  .replace(/^#{1,6}[ \t]*(.+)$/gm, '<b>$1</b>')                          // títulos
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')                                // **negrita**
  .replace(/\*([^*\n]+?)\*/g, '<b>$1</b>')                               // *negrita*
  .replace(/\*/g, '')                                                    // asteriscos sueltos
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const partes = [];
let actual = '';
for (const p of t.split('\n\n')) {
  if ((actual + '\n\n' + p).length > LIMITE && actual) { partes.push(actual); actual = p; }
  else actual = actual ? actual + '\n\n' + p : p;
}
if (actual) partes.push(actual);
const finales = partes.flatMap(p => p.length > LIMITE ? p.replace(/<\/?b>/g, '').match(new RegExp(`[\\s\\S]{1,${LIMITE}}`, 'g')) : [p]);
return finales.map(mensaje => ({ json: { mensaje } }));

// Herramienta: calcular_presupuesto
// Entrada (query): JSON con { "personas": 2, "dias": 3, "nivel": "medio", "entradas_por_persona": 150000 }
let p;
try {
  const txt = String(query || '');
  p = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
} catch (e) {
  return 'Error: envía un JSON como {"personas": 2, "dias": 3, "nivel": "medio", "entradas_por_persona": 150000}';
}

const personas = Math.max(1, parseInt(p.personas) || 1);
const dias = Math.max(1, parseInt(p.dias) || 1);
const nivel = String(p.nivel || 'medio').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const entradas = Math.max(0, Number(p.entradas_por_persona) || 0);

// Costos diarios de referencia por persona (COP)
const tarifas = {
  economico: { alojamiento: 60000, comida: 50000, transporte: 25000, etiqueta: 'Económico (hostal, corrientazo, bus/yipao)' },
  medio:     { alojamiento: 140000, comida: 90000, transporte: 50000, etiqueta: 'Medio (hotel o finca, restaurantes típicos, taxis)' },
  premium:   { alojamiento: 330000, comida: 180000, transporte: 120000, etiqueta: 'Premium (hotel boutique, gastronomía, transporte privado)' },
};
const t = tarifas[nivel] || tarifas.medio;
const noches = Math.max(1, dias - 1);

const fmt = v => '$' + Math.round(v).toLocaleString('es-CO');
const aloj = t.alojamiento * noches * personas;
const com = t.comida * dias * personas;
const trans = t.transporte * dias * personas;
const ent = entradas * personas;
const sub = aloj + com + trans + ent;
const imprevistos = sub * 0.10;
const total = sub + imprevistos;

return [
  `Nivel: ${t.etiqueta} · ${personas} persona(s) · ${dias} día(s) / ${noches} noche(s)`,
  '',
  '| Concepto | Total |',
  '|---|---|',
  `| 🏨 Alojamiento (${noches} noches) | ${fmt(aloj)} |`,
  `| 🍽️ Alimentación | ${fmt(com)} |`,
  `| 🚙 Transporte local | ${fmt(trans)} |`,
  `| 🎟️ Entradas y actividades | ${fmt(ent)} |`,
  `| 🧯 Imprevistos (10 %) | ${fmt(imprevistos)} |`,
  `| **TOTAL** | **${fmt(total)}** |`,
  `| **Por persona** | **${fmt(total / personas)}** |`,
  '',
  'Valores de referencia en pesos colombianos (COP); no incluyen el transporte hasta el Quindío.',
].join('\n');
